291	            path: Some(path.to_owned()),
292	            message: "invalid UTF-8 replaced with U+FFFD".to_owned(),
293	        });
294	    }
295	    let analysis = match analyzer.analyze(path, Box::new(move || Ok(text))) {
296	        Ok(analysis) => analysis,
297	        Err(err) => {
298	            diagnostics.push(skipped(Some(path), format!("could not analyze: {err}")));
299	            return;
300	        }
301	    };
